param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Decoder-Call($Decoder,[string]$Operation,[byte[]]$Source,[int]$Index,[int]$Count,[char[]]$Destination,[int]$OutputIndex,[bool]$Flush){
 try{$n=if($Operation -eq 'Count'){$Decoder.GetCharCount($Source,$Index,$Count,$Flush)}else{$Decoder.GetChars($Source,$Index,$Count,$Destination,$OutputIndex,$Flush)};return [ordered]@{ok=$true;count=$n}}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;message=$e.Message;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.DecoderFallbackException]){$r.unknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}
}

function Span-Bridge([bool]$Write){
 $roDef=[type]'System.ReadOnlySpan`1';$spanDef=[type]'System.Span`1';$ro=$roDef.MakeGenericType([type[]]@([byte]));$span=$spanDef.MakeGenericType([type[]]@([char]));[type[]]$signature=@([Text.Decoder],[byte[]],[int],[int]);[type[]]$native=@($ro)
 if($Write){$signature+=[type[]]@([char[]],[int],[int]);$native+=[type[]]@($span)};$signature+=[type[]]@([bool]);$native+=[type[]]@([bool]);$method=[Text.Decoder].GetMethod($(if($Write){'GetChars'}else{'GetCharCount'}),$native);$dm=[Reflection.Emit.DynamicMethod]::new('UnicodeDecoderSpan'+$Write,[int],$signature);$il=$dm.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$ro.GetConstructor([type[]]@([byte[]],[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$span.GetConstructor([type[]]@([char[]],[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]$(if($Write){7}else{4}));$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$func=[type]('System.Func`'+($signature.Length+1));return $dm.CreateDelegate($func.MakeGenericType([type[]]@($signature+[int])))
}
function Span-Call($Bridge,[object[]]$Arguments){try{return [ordered]@{ok=$true;count=$Bridge.DynamicInvoke($Arguments)}}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.DecoderFallbackException]){$r.unknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}}
$configs=@();foreach($big in @($false,$true)){foreach($strict in @($false,$true)){$configs+=@([ordered]@{bigEndian=$big;strict=$strict;replacement=$null})};foreach($replacement in @(@(),@(67,68),@(0xd800,0xdc00))){$configs+=@([ordered]@{bigEndian=$big;strict=$false;replacement=[int[]]$replacement})}}
$countBridge=Span-Bridge $false;$writeBridge=Span-Bridge $true;$inputs=@(@(),@(65),@(0),@(255),@(0,65),@(65,0),@(0,216),@(216,0),@(0,220),@(220,0),@(0,216,0,220),@(216,0,220,0),@(0,216,65,0),@(216,0,0,65),@(0,216,255),@(216,0,255),@(0,216,0,216,255));$profiles=[Collections.Generic.List[object]]::new()
foreach($config in $configs){
 $encoding=[Text.Encoding]([Text.UnicodeEncoding]::new([bool]$config.bigEndian,$true,[bool]$config.strict)).Clone();if($null -ne $config.replacement){$encoding.DecoderFallback=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$config.replacement))};[int[]]$high=if($config.bigEndian){@(216,0)}else{@(0,216)};$seeds=@(@(),@(65),@($high),@($high+@(0)),@($high+@(220)),@(255));$rows=[Collections.Generic.List[object]]::new()
 foreach($seedId in 0..($seeds.Count-1)){foreach($sourceId in 0..($inputs.Count-1)){$units=$inputs[$sourceId];$length=$units.Length;$views=[Collections.Generic.HashSet[string]]::new();$pairs=@(@(1,$length),@(($length+1),0));if($length){$pairs+=,@($length,1)};foreach($pair in $pairs){$start=[int]$pair[0];$count=[int]$pair[1];if(-not $views.Add("$start,$count")){continue};foreach($flush in @($false,$true)){foreach($capacity in @(0,1,2,3,4,8)){foreach($offset in @(0,2)){
  $decoder=$encoding.GetDecoder();$seed=[byte[]][int[]]$seeds[$seedId];$seedAfter=[char[]](@(99)*8);$seedResult=Decoder-Call $decoder 'Chars' $seed 0 $seed.Length $seedAfter 0 $false;$source=[byte[]](@(221)+$units+@(216));$argsValue=[object[]]::new(5);$argsValue[0]=$decoder;$argsValue[1]=$source;$argsValue[2]=$start;$argsValue[3]=$count;$argsValue[4]=$flush;$countResult=Span-Call $countBridge $argsValue
  $dest=[char[]](@(99)*($offset+$capacity+3));$argsValue=[object[]]::new(8);$argsValue[0]=$decoder;$argsValue[1]=$source;$argsValue[2]=$start;$argsValue[3]=$count;$argsValue[4]=$dest;$argsValue[5]=$offset;$argsValue[6]=$capacity;$argsValue[7]=$flush;$writeResult=Span-Call $writeBridge $argsValue;$tail=[char[]](@(99)*16);$tailResult=Decoder-Call $decoder 'Chars' ([byte[]]@()) 0 0 $tail 0 $true
  $rows.Add([ordered]@{seedId=$seedId;sourceId=$sourceId;start=$start;count=$count;flush=$flush;capacity=$capacity;offset=$offset;seedResult=$seedResult;seedAfter=[int[]]$seedAfter;countResult=$countResult;writeResult=$writeResult;after=[int[]]$dest;tailResult=$tailResult;tailAfter=[int[]]$tail})
 }}}}}};$profiles.Add([ordered]@{config=$config;seeds=$seeds;rows=$rows.ToArray()})
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();inputs=$inputs;profiles=$profiles.ToArray();qualification='NATIVE_UNICODE_DECODER_HEAP_SPANS_REFERENCE_ONLY; NO_JAVA_QUALIFICATION_OR_TASK_ACCEPTANCE'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 19 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF16 decoder span capture: $($profiles.Count) configurations"
